// =====================================================
// PROCESSAMENTO INICIAL - EXTRAÇÃO E VALIDAÇÃO DE DADOS
// =====================================================

const webhookData = $input.all()[0].json;

// Verificar formato da Evolution API
if (!webhookData.body || !webhookData.body.data || !webhookData.body.data.message) {
  return [{ json: { 
    error: true, 
    error_type: 'webhook_invalid',
    error_message: 'Formato de webhook Evolution inválido' 
  }}];
}

const message = webhookData.body.data;

// 🚫 FILTRO ANTI-LOOP: Ignorar mensagens do próprio bot
if (message.key.fromMe === true) {
  console.log('🤖 Mensagem ignorada: enviada pelo próprio bot');
  return [{ json: { 
    ignored: true, 
    reason: 'Mensagem do próprio bot' 
  }}];
}

// Extrair dados básicos
const rawPhoneNumber = message.key.remoteJid.replace('@s.whatsapp.net', '');
const rawMessageText = (message.message?.conversation || message.message?.extendedTextMessage?.text || '').trim();
const messageId = message.key.id;
const timestamp = message.messageTimestamp;

// ✅ FUNÇÃO DE VALIDAÇÃO DE TELEFONE
function validateAndFormatPhone(phone) {
  const cleanPhone = phone.replace(/\D/g, '');

  // Validar formato (10-13 dígitos)
  if (cleanPhone.length < 10 || cleanPhone.length > 13) {
    return {
      valid: false,
      formatted: phone,
      error: 'Número deve ter entre 10 e 13 dígitos'
    };
  }

  // Formatar para padrão brasileiro
  let formattedPhone = cleanPhone;

  // Se tem 13 dígitos e começa com 55, remover código do país
  if (formattedPhone.length === 13 && formattedPhone.startsWith('55')) {
    formattedPhone = formattedPhone.substring(2);
  }

  // Se tem 10 dígitos, adicionar 9 no celular
  if (formattedPhone.length === 10 && !formattedPhone.startsWith('11')) {
    // Para celulares (não fixos), adicionar 9
    if (['21', '11', '31', '41', '51', '61', '71', '81', '85'].includes(formattedPhone.substring(0, 2))) {
      formattedPhone = formattedPhone.substring(0, 2) + '9' + formattedPhone.substring(2);
    }
  }

  return {
    valid: true,
    formatted: formattedPhone,
    original: phone
  };
}

// ✅ FUNÇÃO DE LIMPEZA DE MENSAGEM
function cleanMessage(text) {
  return text
    .trim()
    .replace(/\s+/g, ' ') // Múltiplos espaços em um
    .replace(/[\n\r]/g, ' ') // Quebras de linha em espaços
    .substring(0, 500); // Limitar tamanho
}

// 📱 PROCESSAR TELEFONE
const phoneResult = validateAndFormatPhone(rawPhoneNumber);

// 📝 PROCESSAR MENSAGEM
const cleanedMessage = cleanMessage(rawMessageText);

// 📊 DADOS PROCESSADOS
const processedData = {
  // Dados originais
  raw_phone: rawPhoneNumber,
  raw_message: rawMessageText,
  message_id: messageId,
  timestamp: timestamp,

  // Dados processados
  phone_number: phoneResult.formatted,
  phone_valid: phoneResult.valid,
  phone_error: phoneResult.error || null,

  message_text: cleanedMessage,
  message_valid: cleanedMessage.length > 0,
  message_error: cleanedMessage.length === 0 ? 'Mensagem vazia' : null,

  // Status geral
  processing_valid: phoneResult.valid && cleanedMessage.length > 0,

  // Dados Evolution
  evolution_data: {
    fromMe: message.key.fromMe,
    remoteJid: message.key.remoteJid
  }
};

// 📊 LOG DETALHADO
console.log('📱 Dados processados:', {
  phone: {
    original: rawPhoneNumber,
    formatted: phoneResult.formatted,
    valid: phoneResult.valid,
    error: phoneResult.error
  },
  message: {
    original_length: rawMessageText.length,
    cleaned_length: cleanedMessage.length,
    valid: processedData.message_valid
  },
  overall_valid: processedData.processing_valid
});

return [{ json: processedData }];

// =====================================================
// CLASSIFICADOR INTELIGENTE DE MENSAGENS
// =====================================================

const inputData = $input.all()[0].json;

// Se dados inválidos, ir direto para ajuda
if (!inputData.processing_valid) {
  return [{ json: {
    ...inputData,
    command_type: 'ajuda',
    classification_reason: inputData.phone_error || inputData.message_error || 'Dados inválidos'
  }}];
}

const messageText = inputData.message_text;

// 🧠 FUNÇÕES DE DETECÇÃO
function isNumeric(str) {
  const patterns = [
    /^\d+$/, // 10
    /^\d+[.,]\d+$/, // 10.50 ou 10,50
    /^R\$\s*\d+([.,]\d+)?$/i, // R$ 10 ou R$ 10.50
    /^\$\s*\d+([.,]\d+)?$/, // $10 ou $10.50
    /^\d+[.,]\d{1,2}$/ // 10.5 ou 10.50
  ];
  return patterns.some(pattern => pattern.test(str.trim()));
}

function extractNumber(str) {
  const cleaned = str.replace(/[R$\s]/gi, '').replace(',', '.');
  const num = parseFloat(cleaned);
  return isNaN(num) ? 0 : num;
}

function detectExpenseFormat(text) {
  const words = text.split(/\s+/).filter(w => w.trim() !== '');

  if (words.length < 2) return null;

  // Procurar por números
  const numberPositions = [];
  words.forEach((word, index) => {
    if (isNumeric(word)) {
      numberPositions.push({ index, word, value: extractNumber(word) });
    }
  });

  if (numberPositions.length === 0 || numberPositions[0].value <= 0) return null;

  const valueInfo = numberPositions[0];
  const valueIndex = valueInfo.index;

  let descricao = '';
  let categoria = 'outros';

  // Extrair descrição baseada na posição do valor
  if (valueIndex === 0) {
    descricao = words.slice(1).join(' ');
  } else if (valueIndex === words.length - 1) {
    descricao = words.slice(0, -1).join(' ');
  } else if (valueIndex === words.length - 2 && words.length >= 3) {
    descricao = words.slice(0, -2).join(' ');
    categoria = words[words.length - 1];
  } else {
    const beforeValue = words.slice(0, valueIndex).join(' ');
    const afterValue = words.slice(valueIndex + 1).join(' ');
    descricao = `${beforeValue} ${afterValue}`.trim();
  }

  // Limpeza da descrição
  descricao = descricao
    .replace(/\b(por|de|do|da|no|na|em|com|para|reais?|real|dinheiro|grana)\b/gi, '')
    .trim();

  if (descricao === '') descricao = 'Gasto';

  // Categorização automática
  const categorias = {
    alimentacao: ['café', 'almoço', 'jantar', 'comida', 'lanche', 'pizza', 'hambúrguer', 'restaurante', 'padaria', 'mercado', 'supermercado', 'ifood'],
    transporte: ['uber', 'taxi', 'ônibus', 'metro', 'gasolina', 'combustível', 'passagem', 'viagem', '99'],
    saude: ['remédio', 'farmácia', 'médico', 'consulta', 'exame', 'hospital', 'dentista'],
    lazer: ['cinema', 'teatro', 'show', 'festa', 'bar', 'balada', 'jogo', 'diversão'],
    casa: ['luz', 'água', 'internet', 'aluguel', 'condomínio', 'gás', 'limpeza'],
    roupas: ['roupa', 'camisa', 'calça', 'sapato', 'tênis', 'vestido', 'blusa'],
    educacao: ['curso', 'livro', 'escola', 'faculdade', 'material', 'aula'],
    trabalho: ['material', 'escritório', 'equipamento', 'ferramenta'],
    outros: ['presente', 'gift', 'compra', 'item']
  };

  if (categoria === 'outros') {
    const textLower = `${descricao} ${text}`.toLowerCase();
    for (const [cat, keywords] of Object.entries(categorias)) {
      if (keywords.some(keyword => textLower.includes(keyword))) {
        categoria = cat;
        break;
      }
    }
  }

  return {
    descricao: descricao.charAt(0).toUpperCase() + descricao.slice(1),
    valor: valueInfo.value,
    categoria: categoria.toLowerCase()
  };
}

// 🎯 CLASSIFICAÇÃO PRINCIPAL
let result = { ...inputData };
const lower = messageText.toLowerCase().trim();

// 1. Verificar comandos específicos
if (lower.startsWith('#') || lower.includes('help') || lower.includes('ajuda')) {
  if (lower.includes('dia') || lower.startsWith('#dia')) {
    result.command_type = 'consulta_dia';
  } else if (lower.includes('mês') || lower.includes('mes') || lower.startsWith('#mes') || lower.startsWith('#mês')) {
    result.command_type = 'consulta_mes';
  } else if (lower.includes('conselho') || lower.startsWith('#conselho')) {
    result.command_type = 'conselho';
  } else {
    result.command_type = 'ajuda';
  }
  result.classification_reason = 'Comando detectado';
} else {
  // 2. Tentar identificar como gasto
  const expenseData = detectExpenseFormat(messageText);

  if (expenseData) {
    result.command_type = 'registro';
    result.descricao = expenseData.descricao;
    result.valor = expenseData.valor.toString();
    result.categoria = expenseData.categoria;
    result.valor_valid = true;
    result.classification_reason = 'Gasto identificado';
  } else {
    // 3. Não conseguiu identificar - ir para ajuda
    result.command_type = 'ajuda';
    result.classification_reason = 'Formato não reconhecido';
  }
}

// 📊 LOG DA CLASSIFICAÇÃO
console.log('🎯 Mensagem classificada:', {
  message: messageText,
  command_type: result.command_type,
  reason: result.classification_reason,
  expense_data: result.command_type === 'registro' ? {
    descricao: result.descricao,
    valor: result.valor,
    categoria: result.categoria
  } : null
});

return [{ json: result }];

// =====================================================
// TRATAMENTO DE ERROS E PREPARAÇÃO DE MENSAGENS
// =====================================================

const apiResponse = $input.all()[0].json;
const originalData = $('🎯 Classificar Mensagem').all()[0].json;

let responseData = {
  phone_number: originalData.phone_number,
  message_id: originalData.message_id,
  timestamp: originalData.timestamp,
  command_type: originalData.command_type,
  success: false,
  error: false,
  message: '',
  status_code: null
};

// 🔍 DETECTAR TIPO DE RESPOSTA
if (apiResponse.error) {
  // Erro explícito
  responseData.error = true;
  responseData.message = `❌ *Erro:* ${apiResponse.error}`;
  responseData.status_code = apiResponse.statusCode || 500;
} else if (apiResponse.statusCode && apiResponse.statusCode >= 400) {
  // Erro por status code
  responseData.error = true;
  responseData.message = `❌ *Erro ${apiResponse.statusCode}:* ${apiResponse.message || 'Erro interno do servidor'}`;
  responseData.status_code = apiResponse.statusCode;
} else if (apiResponse.message) {
  // Sucesso com mensagem
  responseData.success = true;
  responseData.message = apiResponse.message;
  responseData.status_code = apiResponse.statusCode || 200;
} else if (apiResponse.response) {
  // Sucesso com response
  responseData.success = true;
  responseData.message = apiResponse.response;
  responseData.status_code = apiResponse.statusCode || 200;
} else {
  // Resposta inesperada
  responseData.error = true;
  responseData.message = '❌ *Erro:* Resposta inesperada do servidor';
  responseData.status_code = 500;
}

// ✅ MENSAGENS DE SUCESSO PADRONIZADAS
if (responseData.success) {
  switch (originalData.command_type) {
    case 'registro':
      responseData.message = `✅ *Gasto registrado com sucesso!*\n\n💰 **${originalData.descricao}**\n💵 R$ ${parseFloat(originalData.valor).toFixed(2)}\n🏷️ Categoria: ${originalData.categoria}\n\n${responseData.message}`;
      break;
    case 'consulta_dia':
    case 'consulta_mes':
      responseData.message = `📊 *Consulta realizada:*\n\n${responseData.message}`;
      break;
    case 'conselho':
      responseData.message = `💡 *Conselho financeiro:*\n\n${responseData.message}`;
      break;
    case 'ajuda':
      responseData.message = `❓ *Como usar o assistente:*\n\n${responseData.message}`;
      break;
  }
}

// 🚨 MENSAGENS DE ERRO PADRONIZADAS
if (responseData.error) {
  // Adicionar informações contextuais ao erro
  const contextInfo = originalData.classification_reason ? `\n\n🔍 *Contexto:* ${originalData.classification_reason}` : '';

  switch (originalData.command_type) {
    case 'registro':
      responseData.message += `\n\n💡 *Exemplo correto:* "Café 5.50" ou "15 almoço alimentação"`;
      break;
    case 'consulta_dia':
    case 'consulta_mes':
      responseData.message += `\n\n💡 *Tente:* "#dia" para gastos de hoje ou "#mês" para o mês atual`;
      break;
  }

  responseData.message += contextInfo;
}

// 📱 PREPARAR PAYLOAD PARA EVOLUTION API
const evolutionPayload = {
  to: `whatsapp:${responseData.phone_number}`,
  text: {
    body: responseData.message
  },
  // Metadados para logs
  metadata: {
    command_type: responseData.command_type,
    success: responseData.success,
    error: responseData.error,
    status_code: responseData.status_code,
    message_id: responseData.message_id
  }
};

// 📊 LOG DETALHADO
console.log('📤 Resposta preparada:', {
  phone: responseData.phone_number,
  command: responseData.command_type,
  success: responseData.success,
  error: responseData.error,
  status: responseData.status_code,
  message_length: responseData.message.length
});

return [{ json: evolutionPayload }];

// =====================================================
// LOG FINAL DE SUCESSO
// =====================================================

const response = $input.all()[0].json;
const metadata = $('⚡ Processar Resposta').all()[0].json.metadata;

const logData = {
  status: 'SUCCESS',
  timestamp: new Date().toISOString(),
  phone: metadata.message_id,
  command: metadata.command_type,
  response_sent: true,
  evolution_response: response
};

console.log('✅ Fluxo concluído com sucesso:', logData);

return [{ json: {
  status: 'success',
  message: 'Mensagem enviada com sucesso',
  data: logData
}}];

// =====================================================
// VERIFICAÇÃO DE AUTORIZAÇÃO (FLUXO LINEAR)
// =====================================================

// Pega os dados do nó "Processar Dados" usando referência
const processNodeItems = $items("🔧 Processar Dados");
if (!processNodeItems.length) {
    throw new Error("Erro: Não encontrei os dados do nó '🔧 Processar Dados'.");
}
const inputData = processNodeItems[0].json;

// Pega os dados do nó anterior (que agora é o Download file)
const driveData = $input.all()[0];

// Se o download da planilha falhou
if (!driveData.binary || !driveData.binary.data) {
  return [{ json: { ...inputData, authorized: false, auth_error: 'Falha ao ler a planilha de autorização.' }}];
}

// Converte o arquivo CSV para texto
const csvContent = Buffer.from(driveData.binary.data.data, 'base64').toString('utf8');
const lines = csvContent.split('\n').map(line => line.trim()).filter(Boolean);
const authorizedNumbers = new Set();

// Lê cada linha da planilha
lines.forEach((line) => {
  const phoneFromSheet = line.split(',')[0].replace(/\D/g, '');
  if (phoneFromSheet.length >= 10) {
    let normalizedPhone = phoneFromSheet.startsWith('55') ? phoneFromSheet.substring(2) : phoneFromSheet;
    authorizedNumbers.add(normalizedPhone);
  }
});

// Verifica se o número do usuário está na lista
const userPhone = inputData.phone_number;
const isAuthorized = authorizedNumbers.has(userPhone);

// Retorna o resultado
return [{ json: {
  ...inputData,
  authorized: isAuthorized,
  auth_error: isAuthorized ? null : 'Número não autorizado.'
}}];
